defmodule Sinestesia.ImageGen.None do
  @moduledoc """
  The provider that renders nothing: every request returns the same black
  1280x720 frame, instantly, as a data URI.

  Exists for runs where the pipeline's TIMING and DIRECTION are wanted but
  its pixels are not — `mix sinestesia.video --motion` on a sequential
  chain generates VIDEO from the director's text and the previous clip's
  final frame, so per-scene stills would be pure spend (and their latency
  would shift reveals later, contaminating the motion timeline). 16:9 at
  720p so anything probing the frame's dimensions sees a real canvas.
  """

  @black_jpeg_b64 ""

  @spec generate(String.t()) :: {:ok, String.t()}
  def generate(_prompt), do: {:ok, "data:image/jpeg;base64," <> @black_jpeg_b64}
end
